#!/bin/bash
# =====================================================================
#  EmulatorJS internet play server -- one-step install (Ubuntu 22.04 / 24.04)
#  Usage: sudo bash ejs-cloud-setup.sh                (creates a room password)
#         sudo bash ejs-cloud-setup.sh yourpass       (your own password: letters and digits only)
#         sudo bash ejs-cloud-setup.sh game.example.com   (also use this domain; it must point to this server)
#  A password and a domain can be given together, in any order.
#  Running it again = update; the password and domain are kept (unless you give new ones)
# =====================================================================
set -e
if [ "$(id -u)" != "0" ]; then exec sudo bash "$0" "$@"; fi

DIR=/opt/emulatorjs-cloud
PORT=8765
TURN_PORT=3478
RELAY_MIN=49160
RELAY_MAX=49250

say() { echo; echo "==== $* ===="; }

NEWKEY=""; NEWDOMAIN=""
for a in "$@"; do
  case "$a" in
    *.*)   # has a dot: a domain name (passwords can't contain dots)
      NEWDOMAIN=$(echo "$a" | tr 'A-Z' 'a-z' | sed -e 's#^[a-z]*://##' -e 's#[:/].*$##' -e 's/\.$//' -e 's/^www\.//')
      if ! echo "$NEWDOMAIN" | grep -Eq '^([a-z0-9]([a-z0-9-]*[a-z0-9])?\.)+[a-z]{2,}$'; then
        echo "This doesn't look like a domain name: $a"; exit 1
      fi ;;
    *) NEWKEY="$a" ;;
  esac
done
if [ -n "$NEWKEY" ] && ! echo "$NEWKEY" | grep -Eq '^[A-Za-z0-9]{4,32}$'; then
  echo "The password must be 4-32 letters and digits"; exit 1
fi

say "1/7 Installing required software (coturn relay, Python)"
export DEBIAN_FRONTEND=noninteractive
apt-get update -y
apt-get install -y coturn python3 curl socat cron

say "2/7 Writing the play server program"
mkdir -p "$DIR"
base64 -d > "$DIR/server.py" <<'B64'
