say "3/7 Finding this server's public IP"
PUB="${PUBLIC_IP:-}"
for u in http://metadata.tencentyun.com/latest/meta-data/public-ipv4 https://ip.sb https://ifconfig.me https://api.ipify.org; do
  [ -n "$PUB" ] && break
  PUB=$(curl -s4 --max-time 4 "$u" 2>/dev/null | tr -d '[:space:]' || true)
  echo "$PUB" | grep -Eq '^[0-9]+\.[0-9]+\.[0-9]+\.[0-9]+$' || PUB=""
done
PRIV=$(hostname -I | awk '{print $1}')
if [ -z "$PUB" ]; then
  echo "Couldn't find the public IP automatically. Run it again like this: sudo PUBLIC_IP=your.public.ip bash $0"; exit 1
fi
echo "Public IP: $PUB    Private IP: $PRIV"

OLDKEY=""; SECRET=""; OLDDOMAIN=""
if [ -f "$DIR/cloud.json" ]; then
  OLDKEY=$(python3 -c "import json;print(json.load(open('$DIR/cloud.json')).get('key',''))" 2>/dev/null || true)
  SECRET=$(python3 -c "import json;print(json.load(open('$DIR/cloud.json')).get('turn_secret',''))" 2>/dev/null || true)
  OLDDOMAIN=$(python3 -c "import json;print(json.load(open('$DIR/cloud.json')).get('domain',''))" 2>/dev/null || true)
fi
KEY="${NEWKEY:-$OLDKEY}"
DOMAIN="${NEWDOMAIN:-$OLDDOMAIN}"
[ -n "$KEY" ] || KEY=$(tr -dc 'a-z0-9' < /dev/urandom | head -c 8)
[ -n "$SECRET" ] || SECRET=$(tr -dc 'A-Za-z0-9' < /dev/urandom | head -c 40)
cat > "$DIR/cloud.json" <<JSON
{"port": $PORT, "key": "$KEY", "turn_secret": "$SECRET", "public_ip": "$PUB", "turn_port": $TURN_PORT, "domain": "$DOMAIN"}
JSON
# Server limits (edit with: sudo ejs-admin -> Server limits). Kept when the script runs again.
if [ ! -f "$DIR/limits.json" ]; then
  echo '{"max_online": 100, "max_rooms": 40, "relay_mbps_user": 8, "relay_mbps_total": 0}' > "$DIR/limits.json"
fi
RELAY_USER=$(python3 -c "import json;print(int(json.load(open('$DIR/limits.json')).get('relay_mbps_user',8))*125000)" 2>/dev/null || echo 1000000)
RELAY_TOTAL=$(python3 -c "import json;print(int(json.load(open('$DIR/limits.json')).get('relay_mbps_total',0))*125000)" 2>/dev/null || echo 0)
chmod 755 "$DIR/data"; chmod 644 "$DIR"/*.py "$DIR"/cloud.json "$DIR"/limits.json "$DIR"/data/badwords.json "$DIR"/data/geoip4.bin

say "4/7 Setting up the network relay (coturn)"
cat > /etc/turnserver.conf <<CONF
# Network relay for EmulatorJS online play (created by ejs-cloud-setup.sh)
listening-port=$TURN_PORT
listening-ip=$PRIV
relay-ip=$PRIV
external-ip=$PUB/$PRIV
min-port=$RELAY_MIN
max-port=$RELAY_MAX
fingerprint
use-auth-secret
static-auth-secret=$SECRET
realm=emulatorjs
no-tls
no-dtls
no-cli
no-multicast-peers
# Don't let the relay reach private networks
denied-peer-ip=10.0.0.0-10.255.255.255
denied-peer-ip=172.16.0.0-172.31.255.255
denied-peer-ip=192.168.0.0-192.168.255.255
denied-peer-ip=127.0.0.0-127.255.255.255
allowed-peer-ip=$PRIV
total-quota=200
stale-nonce=600
simple-log
log-file=/var/log/turnserver.log
CONF
if [ "$RELAY_USER" != "0" ]; then echo "max-bps=$RELAY_USER" >> /etc/turnserver.conf; fi
if [ "$RELAY_TOTAL" != "0" ]; then echo "bps-capacity=$RELAY_TOTAL" >> /etc/turnserver.conf; fi
[ -f /etc/default/coturn ] && sed -i 's/^#*TURNSERVER_ENABLED=.*/TURNSERVER_ENABLED=1/' /etc/default/coturn
systemctl enable coturn >/dev/null 2>&1 || true
systemctl restart coturn

say "5/7 Starting the lobby and making it start on boot"
cat > /etc/systemd/system/emulatorjs-cloud.service <<UNIT
[Unit]
Description=EmulatorJS cloud lobby
After=network-online.target
Wants=network-online.target

[Service]
ExecStart=/usr/bin/python3 $DIR/cloud_server.py
WorkingDirectory=$DIR
DynamicUser=yes
# Extra sandboxing: the server only needs its own folder, its database and the network
ProtectKernelTunables=yes
ProtectKernelModules=yes
ProtectControlGroups=yes
RestrictSUIDSGID=yes
LockPersonality=yes
RestrictNamespaces=yes
# Accounts, friends and stats live here (/var/lib/emulatorjs-cloud); re-running the installer keeps them
StateDirectory=emulatorjs-cloud
Environment=EJS_DB=/var/lib/emulatorjs-cloud/ejs.db
Environment=PYTHONDONTWRITEBYTECODE=1
Restart=always
RestartSec=2

[Install]
WantedBy=multi-user.target
UNIT
systemctl daemon-reload
systemctl enable emulatorjs-cloud >/dev/null 2>&1
systemctl restart emulatorjs-cloud

# If the system firewall is on, open the ports (the cloud console firewall still has to be set by hand)
if command -v ufw >/dev/null && ufw status 2>/dev/null | grep -q "Status: active"; then
  ufw allow $PORT/tcp; ufw allow 80/tcp; ufw allow $TURN_PORT/tcp; ufw allow $TURN_PORT/udp; ufw allow $RELAY_MIN:$RELAY_MAX/udp
fi

say "6/7 Getting an https certificate (free Let's Encrypt IP certificate, renewed every 3 days)"
# The certificate is valid for only 6 days, so it is replaced every 3 days; the lobby doesn't restart and running games aren't dropped
ACME_HOME="$DIR/acme"
ACME_SERVER="${EJS_ACME_SERVER:-letsencrypt}"
ACME_EXTRA=""
[ -n "${EJS_ACME_CA_BUNDLE:-}" ] && ACME_EXTRA="--ca-bundle $EJS_ACME_CA_BUNDLE"
mkdir -p "$DIR/tls" "$ACME_HOME"
base64 -d > "$ACME_HOME/acme.sh" <<'B64'
