IGZpCn0KCm1haW4gIiRAIgo=
B64
chmod 755 "$ACME_HOME/acme.sh"
ACME="$ACME_HOME/acme.sh --home $ACME_HOME --config-home $ACME_HOME"
TLS_OK=""
if $ACME --issue -d "$PUB" --standalone --server "$ACME_SERVER" --cert-profile shortlived --days 3 $ACME_EXTRA \
     --keylength ec-256 --force >/tmp/ejs-acme.log 2>&1 || grep -q "Domains not changed" /tmp/ejs-acme.log; then
  if $ACME --install-cert -d "$PUB" --ecc --key-file "$DIR/tls/key.pem.new" --fullchain-file "$DIR/tls/cert.pem.new" \
       --reloadcmd "chmod 644 $DIR/tls/key.pem.new $DIR/tls/cert.pem.new && mv -f $DIR/tls/cert.pem.new $DIR/tls/cert.pem && mv -f $DIR/tls/key.pem.new $DIR/tls/key.pem" \
       >>/tmp/ejs-acme.log 2>&1 && [ -s "$DIR/tls/cert.pem" ]; then
    TLS_OK=1
  fi
fi
chmod 755 "$DIR/tls"
# Check twice a day and renew before it expires
cat > /etc/cron.d/emulatorjs-cert <<CRON
SHELL=/bin/sh
PATH=/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin
17 3,15 * * * root $ACME --cron $ACME_EXTRA >> /var/log/emulatorjs-cert.log 2>&1
CRON
chmod 644 /etc/cron.d/emulatorjs-cert
systemctl enable cron >/dev/null 2>&1 || true
systemctl restart cron >/dev/null 2>&1 || true
if [ -z "$TLS_OK" ]; then
  echo "Couldn't get the certificate (log: /tmp/ejs-acme.log). Most common reason: TCP port 80 isn't open in the cloud console firewall."
  echo "After opening TCP 80, run it again: sudo bash $0"
fi

DOMAIN_OK=""
if [ -n "$DOMAIN" ]; then
  say "7/7 Getting an https certificate for the domain $DOMAIN (renewed automatically)"
  NAMES=""
  for h in "$DOMAIN" "www.$DOMAIN"; do
    IPS=$(getent ahostsv4 "$h" 2>/dev/null | awk '{print $1}' | sort -u | tr '\n' ' ' || true)
    if echo " $IPS" | grep -q " $PUB "; then
      NAMES="$NAMES -d $h"; echo "$h -> $PUB  OK"
    else
      echo "$h -> ${IPS:-(not found)}  (not this server, skipped)"
    fi
  done
  if ! echo "$NAMES" | grep -q -- "-d $DOMAIN\( \|\$\)"; then
    echo "The domain $DOMAIN doesn't point to this server ($PUB) yet."
    echo "In the cloud console -> Domain DNS, add an A record for $DOMAIN with the value $PUB,"
    echo "wait a few minutes, then run this script again: sudo bash $0"
    echo "(Until then, the IP address keeps working.)"
  else
    RC=0
    $ACME --issue $NAMES --standalone --server "$ACME_SERVER" --keylength ec-256 $ACME_EXTRA >/tmp/ejs-acme-domain.log 2>&1 || RC=$?
    # 0 = new certificate, 2 = the current one is still good (not due for renewal)
    if [ "$RC" = 0 ] || [ "$RC" = 2 ]; then
      if $ACME --install-cert -d "$DOMAIN" --ecc --key-file "$DIR/tls/domain-key.pem.new" --fullchain-file "$DIR/tls/domain-cert.pem.new" \
           --reloadcmd "chmod 644 $DIR/tls/domain-key.pem.new $DIR/tls/domain-cert.pem.new && mv -f $DIR/tls/domain-cert.pem.new $DIR/tls/domain-cert.pem && mv -f $DIR/tls/domain-key.pem.new $DIR/tls/domain-key.pem" \
           >>/tmp/ejs-acme-domain.log 2>&1 && [ -s "$DIR/tls/domain-cert.pem" ]; then
        DOMAIN_OK=1
        echo "Certificate for$(echo "$NAMES" | sed 's/ -d / /g') is ready."
      fi
    fi
    if [ -z "$DOMAIN_OK" ]; then
      echo "Couldn't get the domain certificate (log: /tmp/ejs-acme-domain.log)."
      echo "Common reasons: TCP port 80 isn't open, or the domain was registered only minutes ago."
      echo "The IP address keeps working. Try again later: sudo bash $0"
    fi
  fi
fi

sleep 2
SCHEME=http
[ -n "$TLS_OK" ] && SCHEME=https
OK1=$(curl -sk --max-time 3 -H "X-EJS-Key: $KEY" "$SCHEME://127.0.0.1:$PORT/api/ping" || true)
OK2=$(systemctl is-active coturn || true)
echo
echo "======================================================"
if echo "$OK1" | grep -q '"ok": true' && [ "$OK2" = "active" ]; then
  echo "  Installation complete!"
else
  echo "  Installation may have failed: lobby=[$OK1]  relay=[$OK2]"
  echo "  Take a screenshot of the output above and send it to whoever is helping you."
fi
echo
echo "  On each computer, in EmulatorJS: ⚙ Folder settings -> Internet play server"
if [ -n "$DOMAIN_OK" ]; then
  echo "    Address:  https://$DOMAIN:$PORT"
  echo "    (The old address $SCHEME://$PUB:$PORT keeps working; EmulatorJS switches to the domain by itself.)"
else
  echo "    Address:  $SCHEME://$PUB:$PORT"
fi
if [ -n "$TLS_OK" ]; then echo "    (🔒 https encryption is on; an old http address switches to https by itself)"
else echo "    (⚠ No https encryption yet: open TCP 80, then run this script again)"; fi
echo "    Password: $KEY"
echo
echo "  To manage user accounts later, run:  sudo ejs-admin"
echo
echo "  Remember to open these in the cloud console -> Firewall:"
echo "    TCP $PORT, TCP 80 (for the https certificate), TCP $TURN_PORT, UDP $TURN_PORT, UDP $RELAY_MIN-$RELAY_MAX"
echo "======================================================"
